Running command: cd /workspace/repo-vul/src-vul/htslib && cp header.c /tmp/header.c.bak && python3 - <<'PYEOF'
with open('header.c') as f:
    content = f.read()
old = """    /* Only leafs? Choose the last one! */
    if (!j && hrecs->npg_end > 0) {
        hrecs->pg_end[0] = hrecs->pg_end[hrecs->npg_end-1];
        j = 1;
    }"""
new = """    /* Only leafs? Choose the last one! */
    fprintf(stderr, "DEBUG: npg=%d npg_end=%d j=%d\\n", hrecs->npg, hrecs->npg_end, j);
    if (!j && hrecs->npg_end > 0) {
        hrecs->pg_end[0] = hrecs->pg_end[hrecs->npg_end-1];
        j = 1;
    }"""
assert old in content
content = content.replace(old, new)
with open('header.c', 'w') as f:
    f.write(content)
print("patched")
PYEOF

